import React, { useState } from 'react';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from 'chart.js';
import ManageTeachers from './ManageTeachers';
import TeachersList from './TeachersList';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

export default function LmsDashboard({ userName, handleLogout }) {
  const [currentSubPage, setCurrentSubPage] = useState('Overview');

  const menuItems = [
    { name: 'Overview', icon: '📊' },
    { name: 'Students', icon: '👨‍🎓' },
    { name: 'Teachers & Classes', icon: '🏫' },
    { name: 'Reports', icon: '📋' },
    { name: 'Settings', icon: '⚙️' }
  ];

  const stats = { totalStudents: '1,250', totalTeachers: '45', activeClasses: '120', inactiveStudents: '25' };

  const growthData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May'],
    datasets: [{
      label: 'Enrollment Growth',
      data: [10, 32, 25, 48, 80],
      borderColor: '#15803d',
      backgroundColor: 'rgba(21, 128, 61, 0.1)',
      tension: 0.4,
      fill: true
    }]
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', width: '100%', fontFamily: 'sans-serif', backgroundColor: '#f8fafc' }}>
      
      {/* Admin Header */}
      <div style={{ padding: '20px 40px', background: '#fff', borderBottom: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h2 style={{ margin: 0, fontSize: '18px' }}>Welcome, {userName || 'admin'} 👋</h2>
        <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
          <div style={{ width: '50px', height: '50px', background: '#cbd5e1', borderRadius: '50%' }}></div>
          <button onClick={handleLogout} style={{ background: '#dc2626', color: '#fff', border: 'none', padding: '10px 20px', borderRadius: '6px', cursor: 'pointer' }}>Logout</button>
        </div>
      </div>

      {/* Middle Section */}
      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        
        {/* Sidebar */}
        <div style={{ width: '260px', backgroundColor: '#15803d', color: '#ffffff', padding: '25px 0', flexShrink: 0, overflowY: 'auto' }}>
          <div style={{ padding: '0 25px 20px 25px', borderBottom: '1px solid rgba(255,255,255,0.1)' }}>
            <h2 style={{ fontSize: '20px', fontWeight: 'bold', margin: 0 }}>Admin Panel</h2>
          </div>
          <nav style={{ marginTop: '25px', display: 'flex', flexDirection: 'column', gap: '8px', padding: '0 15px' }}>
            {menuItems.map((item) => (
              <button key={item.name} onClick={() => setCurrentSubPage(item.name)} style={{
                display: 'flex', alignItems: 'center', gap: '14px', width: '100%', padding: '12px 15px',
                backgroundColor: currentSubPage === item.name ? 'rgba(0, 0, 0, 0.2)' : 'transparent',
                color: '#ffffff', border: 'none', borderRadius: '8px', cursor: 'pointer', fontSize: '14px', textAlign: 'left'
              }}>
                <span>{item.icon}</span> <span>{item.name}</span>
              </button>
            ))}
          </nav>
        </div>

        {/* Content Area */}
        <div style={{ flex: 1, padding: '40px', overflowY: 'auto' }}>
          {currentSubPage === 'Overview' && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '30px' }}>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '25px' }}>
                {[
                  { t: 'Total Students', v: stats.totalStudents, i: '👨‍🎓' },
                  { t: 'Total Teachers', v: stats.totalTeachers, i: '👩‍🏫' },
                  { t: 'Active Classes', v: stats.activeClasses, i: '🏫' },
                  { t: 'Inactive Students', v: stats.inactiveStudents, i: '⚠️' }
                ].map((card, i) => (
                  <div key={i} style={{ background: '#ffffff', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
                    <p style={{ color: '#64748b', fontSize: '13px', margin: '0 0 6px 0' }}>{card.t}</p>
                    <h2 style={{ margin: 0, fontSize: '28px' }}>{card.v}</h2>
                  </div>
                ))}
              </div>
              <div style={{ background: '#ffffff', padding: '25px', borderRadius: '16px', height: '300px' }}>
                <Line data={growthData} options={{ maintainAspectRatio: false }} />
              </div>
            </div>
          )}
          {currentSubPage === 'Manage Teachers' && <ManageTeachers />}
        </div>
      </div>
    </div>
  );
}
